// Tests for the Java LCG and the CRT deal (random.hpp).
//
// The reference values were generated by a Java program and are the
// "Java spec" outputs for `new java.util.Random(seed)`:
//
//   seed=0     → nextInt() = -1155484576
//   seed=1     → nextInt() = -1155484576   (Java XORs 0x5DEECE66D)
//   seed=1234  → nextInt() = 1553932502
//
// If our LCG diverges from Java's, every persisted high-score replay
// and every shared bag will be wrong.

#include <algorithm>
#include <cstdint>
#include <string>
#include <vector>

#include "test_harness.hpp"
#include "tt2/random.hpp"

using tt2::Random;

TEST(lcg_java_reference) {
    // Reference values generated by a Java program:
    //
    //   new java.util.Random(0).nextInt()    = -1155484576
    //   new java.util.Random(1).nextInt()    = -1155869325
    //   new java.util.Random(1234).nextInt() = -1517918040
    //
    // If our LCG diverges from Java's, every persisted high-score
    // replay and every shared bag will be wrong.
    {
        Random r(0);
        ASSERT_EQ(r.next_int(), -1155484576);
    }
    {
        Random r(1);
        ASSERT_EQ(r.next_int(), -1155869325);
    }
    {
        Random r(1234);
        ASSERT_EQ(r.next_int(), -1517918040);
    }
}

TEST(lcg_state_persists) {
    Random r(0);
    for (int i = 0; i < 10; ++i) (void)r.next_int();
    const std::uint64_t s1 = r.state();
    r.set_seed(0);
    for (int i = 0; i < 10; ++i) (void)r.next_int();
    ASSERT_EQ(r.state(), s1);
}

TEST(rand_range_is_half_open) {
    Random r(0);
    for (int i = 0; i < 1000; ++i) {
        int x = r.rand(5, 9);  // exclusive upper
        ASSERT_TRUE(x >= 5 && x < 9);
    }
}

TEST(rand_throws_on_empty_range) {
    Random r(0);
    ASSERT_THROWS(r.rand(5, 5));
    ASSERT_THROWS(r.rand(9, 5));
}

TEST(shuffle_is_permutation) {
    Random r(1234);
    std::vector<int> v{1, 2, 3, 4, 5, 6, 7, 8};
    std::vector<int> original = v;
    r.shuffle(v);
    ASSERT_EQ(v.size(), original.size());
    // Same multiset, possibly different order. The fact that we can
    // sort both and compare element-by-element is the check.
    std::sort(v.begin(), v.end());
    std::sort(original.begin(), original.end());
    for (std::size_t i = 0; i < v.size(); ++i) {
        ASSERT_EQ(v[i], original[i]);
    }
}

// ---- deal_order: 0x43c370's deal (game-scene.md §4.1-§4.2) -----------

namespace {
// A fresh generator moved on by `draws` rand() calls: the state a deal
// that drew that many should leave behind.
tt2::CrtRandom crt_after(std::uint32_t seed, int draws) {
    tt2::CrtRandom c(seed);
    for (int i = 0; i < draws; ++i) c.rand();
    return c;
}
}  // namespace

// DL10: srand(1) draws 41, 18467, 6334, 26500, 19169; one pass of
// random_shuffle over "garden" gives "eadrgn", which is neither the order
// before nor the word, so the deal stops after 5 draws.
TEST(deal_order_srand_1_garden) {
    tt2::CrtRandom c(1);
    ASSERT_EQ(tt2::deal_order("garden", "garden", c), std::string("eadrgn"));
    ASSERT_EQ(c.state(), crt_after(1, 5).state());
}

TEST(deal_order_srand_5_garden) {
    tt2::CrtRandom c(5);
    ASSERT_EQ(tt2::deal_order("garden", "garden", c), std::string("nrgdea"));
    ASSERT_EQ(c.state(), crt_after(5, 5).state());
}

TEST(deal_order_srand_12345_airport) {
    tt2::CrtRandom c(12345);
    ASSERT_EQ(tt2::deal_order("airport", "airport", c), std::string("oarptir"));
    ASSERT_EQ(c.state(), crt_after(12345, 6).state());
}

// srand(195): a plain pass over "stone" deals "stone" back. The do-while
// shuffles again (2 passes of 4 draws) and deals "snteo".
TEST(deal_order_reshuffles_a_pass_that_spells_the_word) {
    tt2::CrtRandom plain(195);
    std::string once = "stone";
    plain.shuffle(once);
    ASSERT_EQ(once, std::string("stone"));

    tt2::CrtRandom c(195);
    ASSERT_EQ(tt2::deal_order("stone", "stone", c), std::string("snteo"));
    ASSERT_EQ(c.state(), crt_after(195, 8).state());
}

// A twist: the order before differs from the word. srand(1193)'s first
// pass over "dnaerg" spells "garden", so it is thrown away as well.
TEST(deal_order_twist_rejects_the_word_as_well_as_the_order_before) {
    tt2::CrtRandom plain(1193);
    std::string once = "dnaerg";
    plain.shuffle(once);
    ASSERT_EQ(once, std::string("garden"));

    tt2::CrtRandom c(1193);
    ASSERT_EQ(tt2::deal_order("dnaerg", "garden", c), std::string("rgdnea"));
    ASSERT_EQ(c.state(), crt_after(1193, 10).state());
}

TEST(deal_order_never_deals_the_order_before_or_the_word) {
    for (std::uint32_t seed = 1; seed <= 300; ++seed) {
        tt2::CrtRandom c(seed);
        const std::string dealt = tt2::deal_order("aabbc", "abcab", c);
        ASSERT_TRUE(dealt != "aabbc");
        ASSERT_TRUE(dealt != "abcab");
        std::string sorted = dealt;
        std::sort(sorted.begin(), sorted.end());
        ASSERT_EQ(sorted, std::string("aabbc"));   // the same letters
    }
}

// 0x43c280 refuses fewer than 2 letters and a row of one repeated letter:
// the row comes back as it was and no rand() is drawn.
TEST(deal_order_refusals_draw_nothing) {
    tt2::CrtRandom c(7);
    ASSERT_EQ(tt2::deal_order("aaaaa", "aaaaa", c), std::string("aaaaa"));
    ASSERT_EQ(tt2::deal_order("a", "a", c), std::string("a"));
    ASSERT_EQ(tt2::deal_order("", "garden", c), std::string());
    ASSERT_EQ(c.state(), 7u);
}

// Port guard: two different letters with the word their swap leave no
// order to deal; the exe would loop forever. Unreachable in play (every
// rack and every Lightning word has 5+ letters).
TEST(deal_order_two_letters_and_their_swap_draw_nothing) {
    tt2::CrtRandom c(9);
    ASSERT_EQ(tt2::deal_order("ab", "ba", c), std::string("ab"));
    ASSERT_EQ(c.state(), 9u);
    // With the word equal to the order before, the swap is still dealt.
    ASSERT_EQ(tt2::deal_order("ab", "ab", c), std::string("ba"));
}
